const SLUG_LABELS = {
    interior: 'Interior curte',
    smallGate: 'Poarta mica',
    backyard: 'Spate casa',
    gate2: 'Poarta glisanta 2',
    gate1: 'Poarta glisanta 1',
    fataCasa: 'Fata casa',
    strada: 'Curte strada'
};

function displayName(slug) {
    if (SLUG_LABELS[slug]) return SLUG_LABELS[slug];
    return slug.replace(/_/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2')
        .replace(/\b\w/g, c => c.toUpperCase());
}

const parts = (msg.topic || '').split('/');
const slug = parts[2];
if (!slug) return null;

const state = String(msg.payload || '').toLowerCase().trim();
msg.cameraSlug = slug;
msg.cameraName = SLUG_LABELS[slug] || displayName(slug);
msg.watchdogKey = 'watchdog_state_camera_' + slug;

if (state === 'online') {
    return [msg, null];
}
if (state === 'offline') {
    msg.offlineReason = 'reported';
    return [null, msg];
}
return null;

const SLUG_LABELS = {
    interior: 'Interior curte',
    smallGate: 'Poarta mica',
    backyard: 'Spate casa',
    gate2: 'Poarta glisanta 2',
    gate1: 'Poarta glisanta 1',
    fataCasa: 'Fata casa',
    strada: 'Curte strada'
};

function displayName(slug) {
    if (SLUG_LABELS[slug]) return SLUG_LABELS[slug];
    return slug.replace(/_/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2')
        .replace(/\b\w/g, c => c.toUpperCase());
}

if (msg.cameraSlug && msg.cameraName) return msg;

const parts = (msg.topic || '').split('/');
const slug = parts[2];
if (!slug) return null;

msg.cameraSlug = slug;
msg.cameraName = SLUG_LABELS[slug] || displayName(slug);
msg.watchdogKey = 'watchdog_state_camera_' + slug;
return msg;

const SLUG_LABELS = {
    interior: 'Interior curte',
    smallGate: 'Poarta mica',
    backyard: 'Spate casa',
    gate2: 'Poarta glisanta 2',
    gate1: 'Poarta glisanta 1',
    fataCasa: 'Fata casa',
    strada: 'Curte strada'
};

function displayName(slug) {
    if (SLUG_LABELS[slug]) return SLUG_LABELS[slug];
    return slug.replace(/_/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2')
        .replace(/\b\w/g, c => c.toUpperCase());
}

const parts = (msg.topic || '').split('/');
const slug = parts[2];
if (!slug) return null;

msg.cameraSlug = slug;
msg.cameraName = SLUG_LABELS[slug] || displayName(slug);
msg.watchdogKey = 'watchdog_state_camera_' + slug;
msg.offlineReason = 'timeout';
return msg;

const key = msg.watchdogKey;
if (!key) return null;
const prev = flow.get(key);
if (prev === 'online') return null;
flow.set(key, 'online');
return msg;

const key = msg.watchdogKey;
if (!key) return null;
const prev = flow.get(key);
if (prev === 'offline') return null;
flow.set(key, 'offline');
return msg;

msg.payload = {
    chatId: 991635368,
    type: 'message',
    content: `🟢 *Camera ONLINE*\n\n📷 ${msg.cameraName}\nTopic: ${msg.topic}`,
    parse_mode: 'Markdown'
};
return msg;

const reason = msg.offlineReason === 'reported'
    ? 'Tapo monitor reported offline (ONVIF unreachable).'
    : 'No online heartbeat for 2 minutes. Check tapo-monitor.service and camera ONVIF.';

msg.payload = {
    chatId: 991635368,
    type: 'message',
    content: `🔴 *Camera OFFLINE*\n\n📷 ${msg.cameraName}\n${reason}\nTopic: ${msg.topic}`,
    parse_mode: 'Markdown'
};
return msg;
